  ($d$google/gemini-2.5-pro-preview-2025-06-05$d$::text, '4811a3cf830f'::text, $d$Gemini 2.5 Pro Preview (2025-06-05) was a preview of Google's Gemini 2.5 Pro, a thinking model designed for advanced reasoning, coding, mathematics, and scientific tasks.$d$::text),
  ($d$google/gemini-3-flash$d$::text, 'bef7578e80a7'::text, $d$Gemini 3 Flash is Google's fast Gemini 3 thinking model for agentic workflows, multi-turn chat, and coding assistance.$d$::text),
