  ($d$qwen/qwen2.5-72b$d$::text, '62aa1268af45'::text, $d$Qwen 2.5 72B is the largest model in the Qwen team's Qwen2.5 series of large language models, released in September 2024.$d$::text),
  ($d$qwen/qwen2.5-7b$d$::text, 'f81c4f0b08cc'::text, $d$Qwen 2.5 7B is a model in the Qwen team's Qwen2.5 series of large language models, released in September 2024.$d$::text),
  ($d$qwen/qwen2.5-coder-0.5b$d$::text, 'd11c5c9489cb'::text, $d$Qwen 2.5 Coder 0.5B is a model in the Qwen team's Qwen2.5-Coder series of code-specific language models (formerly known as CodeQwen).$d$::text),
  ($d$qwen/qwen2.5-coder-1.5b$d$::text, '7188fe791f4b'::text, $d$Qwen 2.5 Coder 1.5B is a model in the Qwen team's Qwen2.5-Coder series of code-specific language models (formerly known as CodeQwen).$d$::text),
  ($d$qwen/qwen2.5-coder-14b$d$::text, 'd045216d353f'::text, $d$Qwen 2.5 Coder 14B is a model in the Qwen team's Qwen2.5-Coder series of code-specific language models (formerly known as CodeQwen).$d$::text),
  ($d$qwen/qwen2.5-coder-32b$d$::text, '7b8bb9698638'::text, $d$Qwen 2.5 Coder 32B Instruct is the largest model in the Qwen team's Qwen2.5-Coder series of code-specific language models (formerly known as CodeQwen).$d$::text),
  ($d$qwen/qwen2.5-coder-3b$d$::text, '8340d036844f'::text, $d$Qwen 2.5 Coder 3B is a model in the Qwen team's Qwen2.5-Coder series of code-specific language models (formerly known as CodeQwen).$d$::text),
  ($d$qwen/qwen2.5-coder-7b$d$::text, '9770f06f0e78'::text, $d$Qwen 2.5 Coder 7B is a model in the Qwen team's Qwen2.5-Coder series of code-specific language models (formerly known as CodeQwen).$d$::text),
  ($d$qwen/qwen2.5-math-1.5b$d$::text, '501cf3488b2e'::text, $d$Qwen 2.5 Math 1.5B is a math-specialized model from the Qwen team's Qwen2.5 series.$d$::text),
  ($d$qwen/qwen2.5-math-72b$d$::text, 'b65c6dc6cb24'::text, $d$Qwen 2.5 Math 72B is the largest math-specialized model from the Qwen team's Qwen2.5 series.$d$::text),
  ($d$qwen/qwen2.5-math-7b$d$::text, '39f402ba47b3'::text, $d$Qwen 2.5 Math 7B is a math-specialized model from the Qwen team's Qwen2.5 series.$d$::text),
  ($d$qwen/qwen2.5-math-7b-prm800k$d$::text, '4db025d01f4f'::text, $d$Qwen 2.5 Math 7B PRM800K is a Qwen2.5-Math process reward model trained on the PRM800K dataset, which scores intermediate reasoning steps in math solutions.$d$::text),
  ($d$qwen/qwen2.5-math-prm-72b$d$::text, '72e6e5afdb6f'::text, $d$Qwen 2.5 Math PRM 72B is the Qwen team's process reward model for Qwen2.5-Math, which scores intermediate reasoning steps in math solutions.$d$::text),
  ($d$qwen/qwen2.5-math-prm-7b$d$::text, 'b5b1a8b4b850'::text, $d$Qwen 2.5 Math PRM 7B is the Qwen team's process reward model for Qwen2.5-Math, which scores intermediate reasoning steps in math solutions.$d$::text),
  ($d$qwen/qwen2.5-math-rm-72b$d$::text, '35fc6427c938'::text, $d$Qwen 2.5 Math RM 72B is the Qwen team's reward model for Qwen2.5-Math, used to score math solutions.$d$::text),
  ($d$qwen/qwen3-235b-a22b-2507$d$::text, '2b6afd8c6b3e'::text, $d$Qwen 3 235B A22B Instruct 2507 is a multilingual, instruction-tuned mixture-of-experts language model based on the Qwen3-235B architecture, with 22B active parameters per forward pass.$d$::text),
  ($d$qwen/qwen3-30b-a3b$d$::text, '9eed9e274687'::text, $d$Qwen3 30B A3B is a mixture-of-experts model from the Qwen team's Qwen3 series with 30.5B total and 3.3B active parameters, supporting both thinking and non-thinking modes.$d$::text),
  ($d$qwen/qwen3-coder-30b-a3b-instruct$d$::text, '60349c353a6d'::text, $d$Qwen3-Coder-30B-A3B-Instruct is a 30.5B parameter Mixture-of-Experts (MoE) model with 128 experts (8 active per forward pass), designed for advanced code generation, repository-scale understanding, and agentic tool use.$d$::text),
  ($d$qwen/qwen3-coder-480b-a35b-instruct-turbo$d$::text, '917cc16475f1'::text, $d$Qwen3-Coder-480B-A35B-Instruct is the Qwen team's largest Qwen3 coding model, a 480B-parameter mixture-of-experts model with 35B active parameters for agentic coding and browser use.$d$::text),
  ($d$qwen/qwen3-tts-voicedesign$d$::text, 'da785da45100'::text, $d$Qwen 3 TTS VoiceDesign is the Qwen team's 1.7B text-to-speech model that creates a new voice from a natural-language description.$d$::text),
  ($d$qwen/qwen3.5-flash-02-23$d$::text, 'b440f02c8587'::text, $d$The Qwen3.5 native vision-language Flash models are built on a hybrid architecture that integrates a linear attention mechanism with a sparse mixture-of-experts model, for higher inference efficiency.$d$::text),
  ($d$qwen/qwen3.5-plus-02-15$d$::text, 'a2285739226b'::text, $d$The Qwen3.5 native vision-language Plus models are built on a hybrid architecture that integrates linear attention mechanisms with sparse mixture-of-experts models, for higher inference efficiency.$d$::text),
  ($d$qwen/qwen3.7-max-2026-05-20$d$::text, '9ccd7b6140be'::text, $d$Qwen 3.7 Max (2026-05-20) is a pinned snapshot of Alibaba's proprietary Qwen 3.7 Max model for agentic work, with a native 1M-token context window and an extended thinking mode that can be preserved across turns. Use it for stable behavior across releases; qwen/qwen3.7-max is the rolling alias.$d$::text),
  ($d$qwen/qwen3.8-27b-free$d$::text, '4fce33e17559'::text, $d$Qwen3.8 27B (Free) is a free text-only deployment of Alibaba's open-weight Qwen3.8-27B dense model, released under Apache-2.0, with a 64K-token context window, native tool calling, structured outputs and reasoning mode.$d$::text),
  ($d$qwen/qwen3.8-flash-next$d$::text, '7371777c3f39'::text, $d$Qwen 3.8 Flash Next is an open-weight multimodal Qwen model with text and image input, tool calling, JSON mode, and a 1,048,576-token context window.$d$::text),
  ($d$qwen/qwen3.8-max-preview$d$::text, '5df9dc3cb460'::text, $d$Qwen3.8-Max-Preview is the 2.4T-parameter preview of Qwen 3.8 Max, which debuted through Alibaba Token Plan, Qoder and QoderWork before the full Qwen 3.8 Max release.$d$::text),
  ($d$qwen/qwq-32b-preview$d$::text, '516dc00a2eda'::text, $d$QwQ 32B Preview was the experimental preview of the Qwen team's QwQ 32B reasoning model, released in November 2024.$d$::text),
  ($d$qwen/text-embedding-v3$d$::text, '94bf2573575a'::text, $d$Text Embedding V3 is a proprietary text embedding model from the Qwen team on Alibaba Cloud. It is aimed at semantic search, retrieval, clustering, and RAG pipelines.$d$::text),
  ($d$qwen/text-embedding-v4$d$::text, '2cef4523c623'::text, $d$Text Embedding V4 is a proprietary text embedding model from the Qwen team on Alibaba Cloud. It is aimed at semantic search, retrieval, clustering, and RAG pipelines.$d$::text),
  ($d$qwen/wan2.2-t2v-a14b$d$::text, '6e91721e2c25'::text, $d$Wan2.2-T2V-A14B is Alibaba's open-weight Wan 2.2 text-to-video model, a mixture-of-experts video diffusion model with 14B active parameters.$d$::text),
  ($d$reka/reka-flash-3$d$::text, 'd5d3a65882b3'::text, $d$Reka Flash 3 is a general-purpose, instruction-tuned large language model with 21 billion parameters, developed by Reka. It is suited to general chat, coding tasks, instruction-following, and function calling.$d$::text),
  ($d$relace/relace-apply-3$d$::text, '512525da7c89'::text, $d$Relace Apply 3 is a specialized code-patching LLM that merges AI-suggested edits into existing source files.$d$::text),
  ($d$runway/aleph-2$d$::text, '82700e726da4'::text, $d$Runway Aleph 2.0 is an in-context video editing model from Runway. It applies text instructions and keyframe-guided edits across existing footage while preserving details that are not meant to change.$d$::text),
  ($d$sakana/sakana-namazu$d$::text, 'ef8a5568ee7e'::text, $d$Sakana Namazu is a Japanese-specialized reasoning model from Sakana AI, based on Kimi K2.6 with additional training for Japanese language and business contexts.$d$::text),
  ($d$scaledown/classify-1$d$::text, '50d2cbf82841'::text, $d$ScaleDown Classify-1 answers typed yes/no, choice and score questions with calibrated probabilities instead of generated text.$d$::text),
  ($d$spacex-ai/grok-2-vision-1212$d$::text, '12a075dd5dbe'::text, $d$Grok 2 Vision 1212 is SpaceXAI's December 2024 vision model, which accepts text and image inputs and produces text.$d$::text),
  ($d$spacex-ai/grok-4.1-non-thinking$d$::text, 'ca46ecf61b2c'::text, $d$Grok 4.1 Non Thinking is SpaceXAI's Grok 4.1 model without extended reasoning. It accepts text and image inputs with text output, and is suited for agentic workflows and instruction-following tasks.$d$::text),
  ($d$spacex-ai/grok-4.1-thinking$d$::text, '8ba66bdf3ba0'::text, $d$Grok 4.1 Thinking is the reasoning version of SpaceXAI's Grok 4.1. It accepts text and image inputs with text output, and is suited for agentic workflows and instruction-following tasks.$d$::text),
  ($d$spacex-ai/grok-4.2-beta$d$::text, '98f2996eecd3'::text, $d$Grok 4.20 Beta is a SpaceXAI model released in March 2026, built for fast responses, agentic tool calling, and strict prompt adherence.$d$::text),
  ($d$spacex-ai/grok-4.20$d$::text, 'a9dc57366f4c'::text, $d$Grok 4.20 is a reasoning model from SpaceXAI built for fast responses and agentic tool calling. It supports up to 2M of input context for long documents, codebases, and agent workflows.$d$::text),
  ($d$spacex-ai/grok-4.3$d$::text, '7665aa5c69da'::text, $d$Grok 4.3 is a reasoning model from SpaceXAI. It accepts text and image inputs with text output, and is suited for agentic workflows and instruction-following tasks.$d$::text),
  ($d$stealth/ox-alpha$d$::text, 'b6ea72d6475f'::text, $d$Ox Alpha was an anonymous stealth-preview reasoning model for coding, sustained agentic work, and production workloads. It was later revealed as Z.AI GLM-5.3-Flash and is no longer available under the Ox Alpha name.$d$::text),
  ($d$stepfun/step-3.5-flash$d$::text, '9b225b5c184a'::text, $d$Step 3.5 Flash is an open-source foundation model from StepFun. It is tuned for lower latency and cost-sensitive production use.$d$::text),
  ($d$stepfun/step-3.7-flash$d$::text, '12232bd43100'::text, $d$Step 3.7 Flash is StepFun's multimodal reasoning model for real-world agent, coding, and workflow tasks. It supports text, image, and video inputs with low-latency tool use.$d$::text),
  ($d$tencent/hy-image-v3.5-preview$d$::text, 'be1dd46a4ed0'::text, $d$HY Image v3.5 Preview is Tencent Hunyuan's image generation and reference-based editing model, with output up to 2K.$d$::text),
  ($d$tencent/hy-mt2-1.8b$d$::text, '14fcee161c15'::text, $d$Hy-MT2-1.8B is a compact 1.8B-parameter translation model from Tencent. It supports 33 language pairs and five Chinese dialect and minority-language pairs, with workflows for structured, delimiter-based, contextual, glossary-based, and style-guided translation.$d$::text),
  ($d$tencent/hy-mt2-30b-a3b$d$::text, 'fb5ef07a845d'::text, $d$Hy-MT2-30B-A3B is Tencent's flagship translation model in the Hy-MT2 family. It supports 33 language pairs and five Chinese dialect and minority-language pairs, with workflows for structured, delimiter-based, contextual, glossary-based, and style-guided translation.$d$::text),
  ($d$tencent/hy3-preview$d$::text, '99beca3f94ff'::text, $d$Hy3 Preview is the preview release of Tencent's Hy3, a high-efficiency Mixture-of-Experts model designed for agentic workflows and production use.$d$::text),
  ($d$thedrummer/rocinante-12b$d$::text, '511459e03f39'::text, $d$Rocinante 12B is TheDrummer's creative writing model, designed for engaging storytelling and rich prose.$d$::text),
  ($d$thedrummer/unslopnemo-12b$d$::text, 'd364d0a72e8c'::text, $d$UnslopNemo v4.1 is a model from TheDrummer, the creator of Rocinante, designed for adventure writing and role-play scenarios.$d$::text),
  ($d$typesafe/jev-1.13.0$d$::text, 'e0e4c533803f'::text, $d$TypeSafe Jev evaluates typed yes/no, choice, and score questions against structured state.$d$::text),
  ($d$upstage/solar-decide$d$::text, 'e57d8fad02a7'::text, $d$Upstage Solar Decide answers typed yes/no, choice, and score questions against structured state.$d$::text),
  ($d$writer/palmyra-x5$d$::text, 'd52796115796'::text, $d$Palmyra X5 is Writer's model purpose-built for building and scaling AI agents across the enterprise, with a context window of up to 1 million tokens.$d$::text),
  ($d$xiaomi/mimo-v2-omni$d$::text, '00e5330bc2c3'::text, $d$MiMo V2 Omni was Xiaomi's omni-modal model that natively processes image, video, and audio inputs within a unified architecture. Since June 1, 2026, Xiaomi routes the alias to MiMo V2.5.$d$::text),
  ($d$xiaomi/mimo-v2-pro$d$::text, 'e6861fc551b2'::text, $d$MiMo V2 Pro was Xiaomi's flagship foundation model, with over 1T total parameters and a 1M context length. Since June 1, 2026, Xiaomi routes the alias to MiMo V2.5.$d$::text),
  ($d$xiaomi/mimo-v2.5-pro$d$::text, '364d15589a55'::text, $d$MiMo V2.5 Pro is Xiaomi's MiMo V2.5 model for general agentic work, complex software engineering, and long-horizon tasks.$d$::text),
  ($d$z-ai/glm-4.5$d$::text, '743f0398e9fa'::text, $d$GLM 4.5 is Z.ai's foundation model, released in July 2025, purpose-built for agent-based applications. It uses a Mixture-of-Experts (MoE) architecture and supports a context length of up to 128K tokens.$d$::text),
  ($d$z-ai/glm-4.5-air$d$::text, '096545099c92'::text, $d$GLM 4.5 Air is the lightweight variant of Z.ai's GLM-4.5 model family, purpose-built for agent-centric applications.$d$::text),
  ($d$z-ai/glm-4.6$d$::text, 'c7b5b4bab88d'::text, $d$GLM 4.6 is Z.ai's successor to GLM-4.5, expanding the context window from 128K to 200K tokens for more complex agentic tasks.$d$::text),
  ($d$z-ai/glm-4.7-flash$d$::text, 'cc1d702a4924'::text, $d$GLM 4.7 Flash is Z.ai's 30B-class model that balances performance and efficiency. It is tuned for lower latency and cost-sensitive production use.$d$::text),
  ($d$z-ai/glm-4.7-flash:free$d$::text, 'cc1d702a4924'::text, $d$GLM 4.7 Flash is Z.ai's 30B-class model that balances performance and efficiency. It is tuned for lower latency and cost-sensitive production use.$d$::text)
), applied as (
  update public.v2_models m
  set description = f.new_description,
      updated_at = now()
  from fixes f
  where m.model_slug = f.model_slug
    and case
      when f.old_description_md5 is null then m.description is null
      else left(md5(m.description), 12) = f.old_description_md5
    end
  returning m.model_slug
)
select count(*) as updated_rows, 254 as expected_rows from applied;
